const root=document.querySelector("#root");

function roundTaxLine(numerator, denominator, increment, mode) {
  const scaledDenominator=denominator*increment;
  const units=mode==="nearest_increment_ties_up"
    ? Math.floor((2*numerator+scaledDenominator)/(2*scaledDenominator))
    : Math.floor(numerator/scaledDenominator);
  return units*increment;
}

function formatTax(data) {
  const contract=data.tax;
  if(!contract?.lines?.length||!contract.currency_scale||!contract.display_precision||!contract.display_pattern) return null;

  const lineTaxes=contract.lines.map(({taxable_minor,rate_basis_points})=>taxable_minor*rate_basis_points);
  const scope=contract.scope_operations?.find(({scope_ref})=>scope_ref===contract.rounding_scope_ref);
  const mode=contract.rounding_modes?.find(({mode_ref})=>mode_ref===contract.rounding_mode_ref);
  if(!contract.rounding_increment_minor) return null;

  const denominator=10000;
  const increment=contract.rounding_increment_minor;
  const roundingMode=mode?.operation??"nearest_increment_ties_up";
  const taxMinor=scope?.operation==="sum_then_round"
    ? roundTaxLine(lineTaxes.reduce((sum,numerator)=>sum+numerator,0),denominator,increment,roundingMode)
